#!/bin/bash
# Checks that this project is ready to build, test and ship, and tells you how to fix what is not.
# Generated by https://github.com/InQBarna/xcode-scripts. Run it from the project root:
#
#   ./scripts/doctor.sh              all checks
#   ./scripts/doctor.sh --offline    skip the checks that need network (match repo access, Ruby end of life)
#
# Exit code 1 when something FAILs (the project cannot build/ship), 0 otherwise. WARNs are things to look at.

OFFLINE=""
[[ "$1" == "--offline" ]] && OFFLINE="yes"

FAILS=0
WARNS=0
ok()   { echo "  ok    $1"; }
warn() { echo "  WARN  $1"; [[ -n "$2" ]] && echo "          -> $2"; WARNS=$((WARNS + 1)); }
fail() { echo "  FAIL  $1"; [[ -n "$2" ]] && echo "          -> $2"; FAILS=$((FAILS + 1)); }
section() { echo; echo "$1"; }

if [[ ! -d fastlane && ! -f Gemfile ]] && ! ls -d ./*.xcodeproj > /dev/null 2>&1; then
    echo "Run this from the root of the project (where the .xcodeproj lives)"
    exit 1
fi

# Use the project's Ruby even when this shell has not initialised rbenv
export PATH="$(brew --prefix 2>/dev/null || echo /opt/homebrew)/bin:$PATH"
command -v rbenv > /dev/null && eval "$(rbenv init - bash)"

# --- Xcode and simulators ----------------------------------------------------------------------
section "Xcode"
if xcodebuild -version > /dev/null 2>&1; then
    ok "xcodebuild works ($(xcodebuild -version | head -n 1))"
else
    fail "xcodebuild does not work" "install Xcode and run: sudo xcode-select -s /Applications/Xcode.app"
fi
if [[ -f .xcode-version ]]; then
    WANTED=$(tr -d '[:space:]' < .xcode-version)
    FOUND=$(ls -d /Applications/Xcode[-_]"${WANTED}"*.app 2>/dev/null | sort -V | tail -n 1)
    SELECTED=$(xcodebuild -version 2>/dev/null | head -n 1 | sed -e "s/Xcode //")
    if [[ -n "$FOUND" ]]; then
        ok ".xcode-version $WANTED is installed ($FOUND)"
    elif [[ "$SELECTED" == "$WANTED"* ]]; then
        ok ".xcode-version $WANTED is the selected Xcode"
    else
        warn ".xcode-version asks for Xcode $WANTED, not found in /Applications (selected: $SELECTED)" "xcinstall/install.sh $WANTED, or edit .xcode-version"
    fi
else
    warn "no .xcode-version, builds use whatever Xcode is selected" "xcodebuild -version | head -n 1 | sed -e 's/Xcode //' > .xcode-version"
fi
if xcrun simctl list runtimes available 2>/dev/null | grep -qE "^iOS [0-9.]+ "; then
    ok "an iOS simulator runtime is installed ($(xcrun simctl list runtimes available | grep -E '^iOS [0-9.]+ ' | sed -E 's/^iOS ([0-9.]+) .*/\1/' | sort -V | tail -n 1) is the newest)"
else
    fail "no iOS simulator runtime installed" "Xcode > Settings > Components, or: xcodebuild -downloadPlatform iOS"
fi

# --- Ruby --------------------------------------------------------------------------------------
section "Ruby and gems"
if [[ -f .ruby-version ]]; then
    RUBY_WANTED=$(tr -d '[:space:]' < .ruby-version)
    ok ".ruby-version is $RUBY_WANTED"
    if ruby --version 2>/dev/null | grep -qF "ruby $RUBY_WANTED"; then
        ok "active Ruby matches"
    else
        fail "active Ruby is $(ruby --version 2>/dev/null | cut -d' ' -f2), the project wants $RUBY_WANTED" "run ./scripts/setup.sh"
    fi
    if [[ -z "$OFFLINE" ]]; then
        SERIES=$(echo "$RUBY_WANTED" | cut -d. -f1,2)
        EOL=$(curl -fsS --max-time 8 "https://endoflife.date/api/ruby/$SERIES.json" 2>/dev/null | grep -Eo '"eol": *"[0-9-]+"' | grep -Eo '[0-9]{4}-[0-9]{2}-[0-9]{2}')
        if [[ -n "$EOL" ]]; then
            if [[ "$(date +%Y-%m-%d)" > "$EOL" ]]; then
                warn "Ruby $SERIES reached end of life on $EOL" "change .ruby-version to a supported Ruby and run ./scripts/setup.sh"
            elif [[ "$(date -v+6m +%Y-%m-%d)" > "$EOL" ]]; then
                warn "Ruby $SERIES reaches end of life on $EOL (less than 6 months)" "plan the update of .ruby-version"
            else
                ok "Ruby $SERIES is supported until $EOL"
            fi
        fi
    fi
else
    fail "no .ruby-version" "run ./scripts/setup.sh or create it (rbenv local <version>)"
fi
if [[ -f Gemfile ]]; then
    ok "Gemfile found"
    if bundle check > /dev/null 2>&1; then ok "gems are installed (bundle check)"; else fail "gems are not installed" "run ./scripts/setup.sh"; fi
    if [[ -f Gemfile.lock ]]; then
        if git ls-files --error-unmatch Gemfile.lock > /dev/null 2>&1; then ok "Gemfile.lock is committed"; else warn "Gemfile.lock is not committed, CI would use different gem versions" "git add Gemfile.lock"; fi
    else
        warn "no Gemfile.lock" "run bundle install and commit it"
    fi
else
    fail "no Gemfile" "run create_setup_build_scripts.sh"
fi

# --- Project -----------------------------------------------------------------------------------
section "Xcode project"
PROJECT=$(find . -maxdepth 3 -name "*.xcodeproj" -not -path "*/Pods/*" -not -path "*/.build/*" | head -n 1)
if [[ -z "$PROJECT" ]]; then
    fail "no .xcodeproj found"
else
    ok "project $PROJECT"
    SCHEME_FILE=$(find "$PROJECT" -name "*.xcscheme" -path "*xcshareddata/xcschemes*" | head -n 1)
    if [[ -z "$SCHEME_FILE" ]]; then
        fail "no shared scheme, CI cannot build the project" "Product > Scheme > Manage Schemes > check Shared, then commit it"
    else
        ok "shared scheme $(basename "$SCHEME_FILE")"
        if git ls-files --error-unmatch "$SCHEME_FILE" > /dev/null 2>&1; then ok "shared scheme is committed"; else warn "shared scheme is not committed" "git add $SCHEME_FILE"; fi
        if grep -q 'codeCoverageEnabled = "YES"' "$SCHEME_FILE"; then
            ok "code coverage is enabled in the scheme"
        else
            warn "code coverage is not enabled in the scheme, coverage/cobertura.xml will be empty" "Scheme > Test > Options > Gather coverage for: all targets"
        fi
    fi
    if xcodebuild -project "$PROJECT" -list 2>/dev/null | sed -n '/Targets/,/^$/p' | grep -q "Tests"; then
        ok "project has a test target"
    else
        warn "no test target found" "add a unit test target, ./scripts/build.sh INTENT=test needs it"
    fi
fi
if ls "$(dirname "${PROJECT:-.}")"/Podfile > /dev/null 2>&1; then
    warn "a Podfile is present, this tooling is meant for SPM-only projects" "pod install is not run by setup.sh any more"
fi

# --- fastlane ----------------------------------------------------------------------------------
section "fastlane"
if [[ -f fastlane/Fastfile ]]; then
    ok "fastlane/Fastfile found"
    if grep -q "CommonFastfile" fastlane/Fastfile; then ok "Fastfile imports the common lanes"; else fail "Fastfile does not import CommonFastfile" "see the generated Fastfile template in the xcode-scripts README"; fi
    if grep -q "import_from_git" fastlane/Fastfile && ! grep -q "version:" fastlane/Fastfile; then
        warn "the common lanes are imported without a version, any change in xcode-scripts reaches this project" "add version: '~> 2.0' to import_from_git"
    fi
    if grep -q "gitlab.inqbarna.com" fastlane/Fastfile; then
        fail "Fastfile still imports from gitlab.inqbarna.com (retired)" "use https://github.com/InQBarna/xcode-scripts.git with version: '~> 2.0'"
    fi
    for lane in build test; do
        grep -q "lane :$lane" fastlane/Fastfile && ok "lane $lane" || warn "no '$lane' lane, scripts/build.sh and CI need it"
    done
    if grep -q "iq_beta\|lane :beta" fastlane/Fastfile; then warn "uses the deprecated iq_beta / beta lane" "rename to iq_testflight / ship_testflight"; fi
    if grep -q '"###\|:###' fastlane/Fastfile; then warn "Fastfile still has ### placeholders (firebase id?)" "fill them in fastlane/Fastfile"; fi
else
    fail "no fastlane/Fastfile" "run create_setup_build_scripts.sh"
fi
if [[ -f fastlane/Appfile ]]; then
    grep -q "^team_id" fastlane/Appfile && ok "Appfile has team_id" || fail "Appfile has no team_id"
    grep -q "^app_identifier" fastlane/Appfile && ok "Appfile has app_identifier" || fail "Appfile has no app_identifier"
else
    fail "no fastlane/Appfile"
fi

# --- Signing and distribution ------------------------------------------------------------------
section "Signing and distribution (only needed to ship)"
if [[ -f fastlane/Matchfile ]]; then
    MATCH_URL=$(grep -E '^git_url' fastlane/Matchfile | sed -E 's/^git_url[( ]*"([^"]*)".*/\1/')
    ok "Matchfile found ($MATCH_URL)"
    if [[ -z "$OFFLINE" && -n "$MATCH_URL" ]]; then
        if GIT_TERMINAL_PROMPT=0 git -c http.lowSpeedLimit=1000 -c http.lowSpeedTime=15 ls-remote "$MATCH_URL" > /dev/null 2>&1; then
            ok "match repo is reachable"
        else
            warn "cannot read the match repo" "check your git credentials, or on CI set MATCH_GIT_BASIC_AUTHORIZATION"
        fi
    fi
else
    warn "no fastlane/Matchfile" "run samples/setup_match.sh from xcode-scripts"
fi
[[ -n "$MATCH_PASSPHRASE" ]] && ok "MATCH_PASSPHRASE is set" || warn "MATCH_PASSPHRASE is not set" "export MATCH_PASSPHRASE=... (needed to decrypt certificates)"
if [[ -n "$ASC_KEY_P8" ]]; then
    ok "App Store Connect key from ASC_KEY_P8"
    [[ -n "$ASC_KEY_ID" && -n "$ASC_ISSUER_ID" ]] || warn "ASC_KEY_P8 is set but ASC_KEY_ID / ASC_ISSUER_ID are not (unless they are in the Fastfile)"
elif ls fastlane/AuthKey_*.p8 > /dev/null 2>&1; then
    ok "App Store Connect key file found in fastlane/"
else
    warn "no App Store Connect API key (fastlane/AuthKey_XXXX.p8 or ASC_KEY_P8)" "download it from App Store Connect > Users and Access > Integrations"
fi
if git ls-files 2>/dev/null | grep -q "AuthKey_.*\.p8$"; then
    fail "an App Store Connect private key (.p8) is committed to git" "git rm --cached it, rotate the key in App Store Connect, and add fastlane/AuthKey_*.p8 to .gitignore"
fi
for ignored in deriveddata coverage "fastlane/AuthKey_"; do
    grep -q "$ignored" .gitignore 2>/dev/null || warn ".gitignore does not mention $ignored" "re-run the generator on a copy, or add it by hand"
done

# --- CI ----------------------------------------------------------------------------------------
section "CI"
CI_FOUND=""
[[ -f .github/workflows/ci.yml ]] && { ok "GitHub Actions workflow found"; CI_FOUND="yes"; }
[[ -f Jenkinsfile ]] && { ok "Jenkinsfile found"; CI_FOUND="yes"; }
[[ -z "$CI_FOUND" ]] && warn "no CI configuration" "re-run the generator with CI_PROVIDER=github|jenkins|both"

echo
if [[ $FAILS -gt 0 ]]; then
    echo "$FAILS problem(s) to fix, $WARNS warning(s)"
    exit 1
fi
echo "All good ($WARNS warning(s))"
exit 0
